15. // Package transform provides translations for opentelemetry-go concepts and
16. // structures to otlp structures.
17. package transform
18. 
19. import (
20. 	"context"
21. 	"errors"
22. 	"fmt"
23. 	"strings"
24. 	"sync"
25. 	"time"
26. 
27. 	"go.opentelemetry.io/otel/attribute"
28. 	commonpb "go.opentelemetry.io/proto/otlp/common/v1"
29. 	metricpb "go.opentelemetry.io/proto/otlp/metrics/v1"
30. 	resourcepb "go.opentelemetry.io/proto/otlp/resource/v1"
31. 
32. 	"go.opentelemetry.io/otel/metric/number"
33. 	export "go.opentelemetry.io/otel/sdk/export/metric"
34. 	"go.opentelemetry.io/otel/sdk/export/metric/aggregation"
35. 	"go.opentelemetry.io/otel/sdk/instrumentation"
36. 	"go.opentelemetry.io/otel/sdk/resource"
37. )
38. 
39. var (
40. 	// ErrUnimplementedAgg is returned when a transformation of an unimplemented
41. 	// aggregator is attempted.
42. 	ErrUnimplementedAgg = errors.New("unimplemented aggregator")
43. 
44. 	// ErrIncompatibleAgg is returned when
45. 	// aggregation.Kind implies an interface conversion that has
46. 	// failed
47. 	ErrIncompatibleAgg = errors.New("incompatible aggregation type")
48. 
49. 	// ErrUnknownValueType is returned when a transformation of an unknown value
50. 	// is attempted.
51. 	ErrUnknownValueType = errors.New("invalid value type")
52. 
53. 	// ErrContextCanceled is returned when a context cancellation halts a
54. 	// transformation.
55. 	ErrContextCanceled = errors.New("context canceled")
56. 
57. 	// ErrTransforming is returned when an unexected error is encoutered transforming.
58. 	ErrTransforming = errors.New("transforming failed")
59. )
60. 
61. // result is the product of transforming Records into OTLP Metrics.
62. type result struct {
63. 	Resource               *resource.Resource
64. 	InstrumentationLibrary instrumentation.Library
65. 	Metric                 *metricpb.Metric
66. 	Err                    error
67. }
68. 
69. // toNanos returns the number of nanoseconds since the UNIX epoch.
70. func toNanos(t time.Time) uint64 {
71. 	if t.IsZero() {
72. 		return 0
73. 	}
74. 	return uint64(t.UnixNano())
75. }
76. 
77. // CheckpointSet transforms all records contained in a checkpoint into
78. // batched OTLP ResourceMetrics.
79. func CheckpointSet(ctx context.Context, exportSelector export.ExportKindSelector, cps export.CheckpointSet, numWorkers uint) ([]*metricpb.ResourceMetrics, error) {
80. 	records, errc := source(ctx, exportSelector, cps)
81. 
82. 	// Start a fixed number of goroutines to transform records.
83. 	transformed := make(chan result)
84. 	var wg sync.WaitGroup
85. 	wg.Add(int(numWorkers))
86. 	for i := uint(0); i < numWorkers; i++ {
87. 		go func() {
88. 			defer wg.Done()
89. 			transformer(ctx, exportSelector, records, transformed)
90. 		}()
91. 	}
92. 	go func() {
93. 		wg.Wait()
94. 		close(transformed)
95. 	}()
96. 
97. 	// Synchronously collect the transformed records and transmit.
98. 	rms, err := sink(ctx, transformed)
99. 	if err != nil {
100. 		return nil, err
101. 	}
102. 
103. 	// source is complete, check for any errors.
104. 	if err := <-errc; err != nil {
105. 		return nil, err
106. 	}
107. 	return rms, nil
108. }
109. 
110. // source starts a goroutine that sends each one of the Records yielded by
111. // the CheckpointSet on the returned chan. Any error encoutered will be sent
112. // on the returned error chan after seeding is complete.
113. func source(ctx context.Context, exportSelector export.ExportKindSelector, cps export.CheckpointSet) (<-chan export.Record, <-chan error) {
114. 	errc := make(chan error, 1)
115. 	out := make(chan export.Record)
116. 	// Seed records into process.
117. 	go func() {
118. 		defer close(out)
119. 		// No select is needed since errc is buffered.
120. 		errc <- cps.ForEach(exportSelector, func(r export.Record) error {
121. 			select {
122. 			case <-ctx.Done():
123. 				return ErrContextCanceled
124. 			case out <- r:
125. 			}
126. 			return nil
127. 		})
128. 	}()
129. 	return out, errc
130. }
131. 
132. // transformer transforms records read from the passed in chan into
133. // OTLP Metrics which are sent on the out chan.
134. func transformer(ctx context.Context, exportSelector export.ExportKindSelector, in <-chan export.Record, out chan<- result) {
135. 	for r := range in {
136. 		m, err := Record(exportSelector, r)
137. 		// Propagate errors, but do not send empty results.
138. 		if err == nil && m == nil {
139. 			continue
140. 		}
141. 		res := result{
142. 			Resource: r.Resource(),
143. 			InstrumentationLibrary: instrumentation.Library{
144. 				Name:    r.Descriptor().InstrumentationName(),
145. 				Version: r.Descriptor().InstrumentationVersion(),
146. 			},
147. 			Metric: m,
148. 			Err:    err,
149. 		}
150. 		select {
151. 		case <-ctx.Done():
152. 			return
153. 		case out <- res:
154. 		}
155. 	}
156. }
157. 
158. // sink collects transformed Records and batches them.
159. //
160. // Any errors encoutered transforming input will be reported with an
161. // ErrTransforming as well as the completed ResourceMetrics. It is up to the
162. // caller to handle any incorrect data in these ResourceMetrics.
163. func sink(ctx context.Context, in <-chan result) ([]*metricpb.ResourceMetrics, error) {
164. 	var errStrings []string
165. 
166. 	type resourceBatch struct {
167. 		Resource *resourcepb.Resource
168. 		// Group by instrumentation library name and then the MetricDescriptor.
169. 		InstrumentationLibraryBatches map[instrumentation.Library]map[string]*metricpb.Metric
170. 	}
171. 
172. 	// group by unique Resource string.
173. 	grouped := make(map[attribute.Distinct]resourceBatch)
174. 	for res := range in {
175. 		if res.Err != nil {
176. 			errStrings = append(errStrings, res.Err.Error())
177. 			continue
178. 		}
179. 
180. 		rID := res.Resource.Equivalent()
181. 		rb, ok := grouped[rID]
182. 		if !ok {
183. 			rb = resourceBatch{
184. 				Resource:                      Resource(res.Resource),
185. 				InstrumentationLibraryBatches: make(map[instrumentation.Library]map[string]*metricpb.Metric),
186. 			}
187. 			grouped[rID] = rb
188. 		}
189. 
190. 		mb, ok := rb.InstrumentationLibraryBatches[res.InstrumentationLibrary]
191. 		if !ok {
192. 			mb = make(map[string]*metricpb.Metric)
193. 			rb.InstrumentationLibraryBatches[res.InstrumentationLibrary] = mb
194. 		}
195. 
196. 		mID := res.Metric.GetName()
197. 		m, ok := mb[mID]
198. 		if !ok {
199. 			mb[mID] = res.Metric
200. 			continue
201. 		}
202. 		switch res.Metric.Data.(type) {
203. 		case *metricpb.Metric_IntGauge:
204. 			m.GetIntGauge().DataPoints = append(m.GetIntGauge().DataPoints, res.Metric.GetIntGauge().DataPoints...)
205. 		case *metricpb.Metric_IntHistogram:
206. 			m.GetIntHistogram().DataPoints = append(m.GetIntHistogram().DataPoints, res.Metric.GetIntHistogram().DataPoints...)
207. 		case *metricpb.Metric_IntSum:
208. 			m.GetIntSum().DataPoints = append(m.GetIntSum().DataPoints, res.Metric.GetIntSum().DataPoints...)
209. 		case *metricpb.Metric_DoubleGauge:
210. 			m.GetDoubleGauge().DataPoints = append(m.GetDoubleGauge().DataPoints, res.Metric.GetDoubleGauge().DataPoints...)
211. 		case *metricpb.Metric_DoubleHistogram:
212. 			m.GetDoubleHistogram().DataPoints = append(m.GetDoubleHistogram().DataPoints, res.Metric.GetDoubleHistogram().DataPoints...)
213. 		case *metricpb.Metric_DoubleSum:
214. 			m.GetDoubleSum().DataPoints = append(m.GetDoubleSum().DataPoints, res.Metric.GetDoubleSum().DataPoints...)
215. 		default:
216. 		}
217. 	}
218. 
219. 	if len(grouped) == 0 {
220. 		return nil, nil
221. 	}
222. 
223. 	var rms []*metricpb.ResourceMetrics
224. 	for _, rb := range grouped {
225. 		rm := &metricpb.ResourceMetrics{Resource: rb.Resource}
226. 		for il, mb := range rb.InstrumentationLibraryBatches {
227. 			ilm := &metricpb.InstrumentationLibraryMetrics{
228. 				Metrics: make([]*metricpb.Metric, 0, len(mb)),
229. 			}
230. 			if il != (instrumentation.Library{}) {
231. 				ilm.InstrumentationLibrary = &commonpb.InstrumentationLibrary{
232. 					Name:    il.Name,
233. 					Version: il.Version,
234. 				}
235. 			}
236. 			for _, m := range mb {
237. 				ilm.Metrics = append(ilm.Metrics, m)
238. 			}
239. 			rm.InstrumentationLibraryMetrics = append(rm.InstrumentationLibraryMetrics, ilm)
240. 		}
241. 		rms = append(rms, rm)
242. 	}
243. 
244. 	// Report any transform errors.
245. 	if len(errStrings) > 0 {
246. 		return rms, fmt.Errorf("%w:\n -%s", ErrTransforming, strings.Join(errStrings, "\n -"))
247. 	}
248. 	return rms, nil
249. }
250. 
251. // Record transforms a Record into an OTLP Metric. An ErrIncompatibleAgg
252. // error is returned if the Record Aggregator is not supported.
253. func Record(exportSelector export.ExportKindSelector, r export.Record) (*metricpb.Metric, error) {
254. 	agg := r.Aggregation()
255. 	switch agg.Kind() {
256. 	case aggregation.MinMaxSumCountKind:
257. 		mmsc, ok := agg.(aggregation.MinMaxSumCount)
258. 		if !ok {
259. 			return nil, fmt.Errorf("%w: %T", ErrIncompatibleAgg, agg)
260. 		}
261. 		return minMaxSumCount(r, mmsc)
262. 
263. 	case aggregation.HistogramKind:
264. 		h, ok := agg.(aggregation.Histogram)
265. 		if !ok {
266. 			return nil, fmt.Errorf("%w: %T", ErrIncompatibleAgg, agg)
267. 		}
268. 		return histogramPoint(r, exportSelector.ExportKindFor(r.Descriptor(), aggregation.HistogramKind), h)
269. 
270. 	case aggregation.SumKind:
271. 		s, ok := agg.(aggregation.Sum)
272. 		if !ok {
273. 			return nil, fmt.Errorf("%w: %T", ErrIncompatibleAgg, agg)
274. 		}
275. 		sum, err := s.Sum()
276. 		if err != nil {
277. 			return nil, err
278. 		}
279. 		return sumPoint(r, sum, r.StartTime(), r.EndTime(), exportSelector.ExportKindFor(r.Descriptor(), aggregation.SumKind), r.Descriptor().InstrumentKind().Monotonic())
280. 
281. 	case aggregation.LastValueKind:
282. 		lv, ok := agg.(aggregation.LastValue)
283. 		if !ok {
284. 			return nil, fmt.Errorf("%w: %T", ErrIncompatibleAgg, agg)
285. 		}
286. 		value, tm, err := lv.LastValue()
287. 		if err != nil {
288. 			return nil, err
289. 		}
290. 		return gaugePoint(r, value, time.Time{}, tm)
291. 
292. 	case aggregation.ExactKind:
293. 		e, ok := agg.(aggregation.Points)
294. 		if !ok {
295. 			return nil, fmt.Errorf("%w: %T", ErrIncompatibleAgg, agg)
296. 		}
297. 		pts, err := e.Points()
298. 		if err != nil {
299. 			return nil, err
300. 		}
301. 
302. 		return gaugeArray(r, pts)
303. 
304. 	default:
305. 		return nil, fmt.Errorf("%w: %T", ErrUnimplementedAgg, agg)
306. 	}
307. }
308. 
309. func gaugeArray(record export.Record, points []aggregation.Point) (*metricpb.Metric, error) {
310. 	desc := record.Descriptor()
311. 	labels := record.Labels()
312. 	m := &metricpb.Metric{
313. 		Name:        desc.Name(),
314. 		Description: desc.Description(),
315. 		Unit:        string(desc.Unit()),
316. 	}
317. 
318. 	pbLabels := stringKeyValues(labels.Iter())
319. 
320. 	switch nk := desc.NumberKind(); nk {
321. 	case number.Int64Kind:
322. 		var pts []*metricpb.IntDataPoint
323. 		for _, s := range points {
324. 			pts = append(pts, &metricpb.IntDataPoint{
325. 				Labels:            pbLabels,
326. 				StartTimeUnixNano: toNanos(record.StartTime()),
327. 				TimeUnixNano:      toNanos(record.EndTime()),
328. 				Value:             s.Number.CoerceToInt64(nk),
329. 			})
330. 		}
331. 		m.Data = &metricpb.Metric_IntGauge{
332. 			IntGauge: &metricpb.IntGauge{
333. 				DataPoints: pts,
334. 			},
335. 		}
336. 
337. 	case number.Float64Kind:
338. 		var pts []*metricpb.DoubleDataPoint
339. 		for _, s := range points {
340. 			pts = append(pts, &metricpb.DoubleDataPoint{
341. 				Labels:            pbLabels,
342. 				StartTimeUnixNano: toNanos(record.StartTime()),
343. 				TimeUnixNano:      toNanos(record.EndTime()),
344. 				Value:             s.Number.CoerceToFloat64(nk),
345. 			})
346. 		}
347. 		m.Data = &metricpb.Metric_DoubleGauge{
348. 			DoubleGauge: &metricpb.DoubleGauge{
349. 				DataPoints: pts,
350. 			},
351. 		}
352. 
353. 	default:
354. 		return nil, fmt.Errorf("%w: %v", ErrUnknownValueType, nk)
355. 	}
356. 
357. 	return m, nil
358. }
359. 
360. func gaugePoint(record export.Record, num number.Number, start, end time.Time) (*metricpb.Metric, error) {
361. 	desc := record.Descriptor()
362. 	labels := record.Labels()
363. 
364. 	m := &metricpb.Metric{
365. 		Name:        desc.Name(),
366. 		Description: desc.Description(),
367. 		Unit:        string(desc.Unit()),
368. 	}
369. 
370. 	switch n := desc.NumberKind(); n {
371. 	case number.Int64Kind:
372. 		m.Data = &metricpb.Metric_IntGauge{
373. 			IntGauge: &metricpb.IntGauge{
374. 				DataPoints: []*metricpb.IntDataPoint{
375. 					{
376. 						Value:             num.CoerceToInt64(n),
377. 						Labels:            stringKeyValues(labels.Iter()),
378. 						StartTimeUnixNano: toNanos(start),
379. 						TimeUnixNano:      toNanos(end),
380. 					},
381. 				},
382. 			},
383. 		}
384. 	case number.Float64Kind:
385. 		m.Data = &metricpb.Metric_DoubleGauge{
386. 			DoubleGauge: &metricpb.DoubleGauge{
387. 				DataPoints: []*metricpb.DoubleDataPoint{
388. 					{
389. 						Value:             num.CoerceToFloat64(n),
390. 						Labels:            stringKeyValues(labels.Iter()),
391. 						StartTimeUnixNano: toNanos(start),
392. 						TimeUnixNano:      toNanos(end),
393. 					},
394. 				},
395. 			},
396. 		}
397. 	default:
398. 		return nil, fmt.Errorf("%w: %v", ErrUnknownValueType, n)
399. 	}
400. 
401. 	return m, nil
402. }
403. 
404. func exportKindToTemporality(ek export.ExportKind) metricpb.AggregationTemporality {
405. 	switch ek {
406. 	case export.DeltaExportKind:
407. 		return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_DELTA
408. 	case export.CumulativeExportKind:
409. 		return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_CUMULATIVE
410. 	}
411. 	return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_UNSPECIFIED
