48. // Keep it in sync with golang's DefaultTransport from net/http! We
49. // have our own copy to avoid handling a situation where the
50. // DefaultTransport is overwritten with some different implementation
51. // of http.RoundTripper or it's modified by other package.
52. var ourTransport *http.Transport = &http.Transport{
53. 	Proxy: http.ProxyFromEnvironment,
54. 	DialContext: (&net.Dialer{
55. 		Timeout:   30 * time.Second,
56. 		KeepAlive: 30 * time.Second,
57. 		DualStack: true,
58. 	}).DialContext,
59. 	ForceAttemptHTTP2:     true,
60. 	MaxIdleConns:          100,
61. 	IdleConnTimeout:       90 * time.Second,
62. 	TLSHandshakeTimeout:   10 * time.Second,
63. 	ExpectContinueTimeout: 1 * time.Second,
64. }
