66. type driver struct {
67. 	metricsDriver signalDriver
68. 	tracesDriver  signalDriver
69. 	cfg           otlpconfig.Config
70. 
71. 	stopCh chan struct{}
72. }
73. 
74. type signalDriver struct {
75. 	name       string
76. 	cfg        otlpconfig.SignalConfig
77. 	generalCfg otlpconfig.Config
78. 	client     *http.Client
79. 	stopCh     chan struct{}
80. }
81. 
82. var _ otlp.ProtocolDriver = (*driver)(nil)
83. 
84. // NewDriver creates a new HTTP driver.
85. func NewDriver(opts ...Option) otlp.ProtocolDriver {
86. 	cfg := otlpconfig.NewDefaultConfig()
87. 	otlpconfig.ApplyHTTPEnvConfigs(&cfg)
88. 	for _, opt := range opts {
89. 		opt.ApplyHTTPOption(&cfg)
90. 	}
91. 
92. 	for pathPtr, defaultPath := range map[*string]string{
93. 		&cfg.Traces.URLPath:  DefaultTracesPath,
94. 		&cfg.Metrics.URLPath: DefaultMetricsPath,
95. 	} {
96. 		tmp := strings.TrimSpace(*pathPtr)
97. 		if tmp == "" {
98. 			tmp = defaultPath
99. 		} else {
100. 			tmp = path.Clean(tmp)
101. 			if !path.IsAbs(tmp) {
102. 				tmp = fmt.Sprintf("/%s", tmp)
103. 			}
104. 		}
105. 		*pathPtr = tmp
106. 	}
107. 	if cfg.MaxAttempts <= 0 {
108. 		cfg.MaxAttempts = DefaultMaxAttempts
109. 	}
110. 	if cfg.MaxAttempts > DefaultMaxAttempts {
111. 		cfg.MaxAttempts = DefaultMaxAttempts
112. 	}
113. 	if cfg.Backoff <= 0 {
114. 		cfg.Backoff = DefaultBackoff
115. 	}
116. 
117. 	metricsClient := &http.Client{
118. 		Transport: ourTransport,
119. 		Timeout:   cfg.Metrics.Timeout,
120. 	}
121. 	if cfg.Metrics.TLSCfg != nil {
122. 		transport := ourTransport.Clone()
123. 		transport.TLSClientConfig = cfg.Metrics.TLSCfg
124. 		metricsClient.Transport = transport
125. 	}
126. 
127. 	tracesClient := &http.Client{
128. 		Transport: ourTransport,
129. 		Timeout:   cfg.Traces.Timeout,
130. 	}
131. 	if cfg.Traces.TLSCfg != nil {
132. 		transport := ourTransport.Clone()
133. 		transport.TLSClientConfig = cfg.Traces.TLSCfg
134. 		tracesClient.Transport = transport
135. 	}
136. 
137. 	stopCh := make(chan struct{})
138. 	return &driver{
139. 		tracesDriver: signalDriver{
140. 			name:       "traces",
141. 			cfg:        cfg.Traces,
142. 			generalCfg: cfg,
143. 			stopCh:     stopCh,
144. 			client:     tracesClient,
145. 		},
146. 		metricsDriver: signalDriver{
147. 			name:       "metrics",
148. 			cfg:        cfg.Metrics,
149. 			generalCfg: cfg,
150. 			stopCh:     stopCh,
151. 			client:     metricsClient,
152. 		},
153. 		cfg:    cfg,
154. 		stopCh: stopCh,
155. 	}
156. }
157. 
158. // Start implements otlp.ProtocolDriver.
159. func (d *driver) Start(ctx context.Context) error {
160. 	// nothing to do
161. 	return nil
162. }
163. 
164. // Stop implements otlp.ProtocolDriver.
165. func (d *driver) Stop(ctx context.Context) error {
166. 	close(d.stopCh)
167. 	return nil
168. }
169. 
170. // ExportMetrics implements otlp.ProtocolDriver.
171. func (d *driver) ExportMetrics(ctx context.Context, cps metricsdk.CheckpointSet, selector metricsdk.ExportKindSelector) error {
172. 	rms, err := transform.CheckpointSet(ctx, selector, cps, 1)
173. 	if err != nil {
174. 		return err
175. 	}
176. 	if len(rms) == 0 {
177. 		return nil
178. 	}
179. 	pbRequest := &colmetricspb.ExportMetricsServiceRequest{
180. 		ResourceMetrics: rms,
181. 	}
182. 	rawRequest, err := d.marshal(pbRequest)
183. 	if err != nil {
184. 		return err
185. 	}
186. 	return d.metricsDriver.send(ctx, rawRequest)
187. }
188. 
189. // ExportTraces implements otlp.ProtocolDriver.
190. func (d *driver) ExportTraces(ctx context.Context, ss []tracesdk.ReadOnlySpan) error {
191. 	protoSpans := transform.Spans(ss)
192. 	if len(protoSpans) == 0 {
193. 		return nil
194. 	}
195. 	pbRequest := &coltracepb.ExportTraceServiceRequest{
196. 		ResourceSpans: protoSpans,
197. 	}
198. 	rawRequest, err := d.marshal(pbRequest)
199. 	if err != nil {
200. 		return err
201. 	}
202. 	return d.tracesDriver.send(ctx, rawRequest)
203. }
204. 
205. func (d *driver) marshal(msg proto.Message) ([]byte, error) {
206. 	if d.cfg.Marshaler == otlp.MarshalJSON {
207. 		return jsonpb.Marshal(msg)
208. 	}
209. 	return proto.Marshal(msg)
210. }
211. 
212. func (d *signalDriver) send(ctx context.Context, rawRequest []byte) error {
213. 	address := fmt.Sprintf("%s://%s%s", d.getScheme(), d.cfg.Endpoint, d.cfg.URLPath)
214. 	var cancel context.CancelFunc
215. 	ctx, cancel = d.contextWithStop(ctx)
216. 	defer cancel()
217. 	for i := 0; i < d.generalCfg.MaxAttempts; i++ {
218. 		response, err := d.singleSend(ctx, rawRequest, address)
219. 		if err != nil {
220. 			return err
221. 		}
222. 		// We don't care about the body, so try to read it
223. 		// into /dev/null and close it immediately. The
224. 		// reading part is to facilitate connection reuse.
225. 		_, _ = io.Copy(ioutil.Discard, response.Body)
226. 		_ = response.Body.Close()
227. 		switch response.StatusCode {
228. 		case http.StatusOK:
229. 			return nil
230. 		case http.StatusTooManyRequests:
231. 			fallthrough
232. 		case http.StatusServiceUnavailable:
233. 			select {
234. 			case <-time.After(getWaitDuration(d.generalCfg.Backoff, i)):
235. 				continue
236. 			case <-ctx.Done():
237. 				return ctx.Err()
238. 			}
239. 		default:
240. 			return fmt.Errorf("failed to send %s to %s with HTTP status %s", d.name, address, response.Status)
241. 		}
242. 	}
243. 	return fmt.Errorf("failed to send data to %s after %d tries", address, d.generalCfg.MaxAttempts)
244. }
