246. func (d *signalDriver) getScheme() string {
247. 	if d.cfg.Insecure {
248. 		return "http"
249. 	}
250. 	return "https"
251. }
252. 
253. func getWaitDuration(backoff time.Duration, i int) time.Duration {
254. 	// Strategy: after nth failed attempt, attempt resending after
255. 	// k * initialBackoff + jitter, where k is a random number in
256. 	// range [0, 2^n-1), and jitter is a random percentage of
257. 	// initialBackoff from [-5%, 5%).
258. 	//
259. 	// Based on
260. 	// https://en.wikipedia.org/wiki/Exponential_backoff#Example_exponential_backoff_algorithm
261. 	//
262. 	// Jitter is our addition.
263. 
264. 	// There won't be an overflow, since i is capped to
265. 	// DefaultMaxAttempts (5).
266. 	upperK := (int64)(1) << (i + 1)
267. 	jitterPercent := (rand.Float64() - 0.5) / 10.
268. 	jitter := jitterPercent * (float64)(backoff)
269. 	k := rand.Int63n(upperK)
270. 	return (time.Duration)(k)*backoff + (time.Duration)(jitter)
271. }
272. 
273. func (d *signalDriver) contextWithStop(ctx context.Context) (context.Context, context.CancelFunc) {
274. 	// Unify the parent context Done signal with the driver's stop
275. 	// channel.
276. 	ctx, cancel := context.WithCancel(ctx)
277. 	go func(ctx context.Context, cancel context.CancelFunc) {
278. 		select {
279. 		case <-ctx.Done():
280. 			// Nothing to do, either cancelled or deadline
281. 			// happened.
282. 		case <-d.stopCh:
283. 			cancel()
284. 		}
285. 	}(ctx, cancel)
286. 	return ctx, cancel
287. }
288. 
289. func (d *signalDriver) singleSend(ctx context.Context, rawRequest []byte, address string) (*http.Response, error) {
290. 	request, err := http.NewRequestWithContext(ctx, http.MethodPost, address, nil)
291. 	if err != nil {
292. 		return nil, err
293. 	}
294. 	bodyReader, contentLength, headers := d.prepareBody(rawRequest)
295. 	// Not closing bodyReader through defer, the HTTP Client's
296. 	// Transport will do it for us
297. 	request.Body = bodyReader
298. 	request.ContentLength = contentLength
299. 	for key, values := range headers {
300. 		for _, value := range values {
301. 			request.Header.Add(key, value)
302. 		}
303. 	}
304. 	return d.client.Do(request)
305. }
306. 
307. func (d *signalDriver) prepareBody(rawRequest []byte) (io.ReadCloser, int64, http.Header) {
308. 	var bodyReader io.ReadCloser
309. 	headers := http.Header{}
310. 	for k, v := range d.cfg.Headers {
311. 		headers.Set(k, v)
312. 	}
313. 	contentLength := (int64)(len(rawRequest))
314. 	if d.generalCfg.Marshaler == otlp.MarshalJSON {
315. 		headers.Set("Content-Type", contentTypeJSON)
316. 	} else {
317. 		headers.Set("Content-Type", contentTypeProto)
318. 	}
319. 	requestReader := bytes.NewBuffer(rawRequest)
320. 	switch d.cfg.Compression {
321. 	case otlp.NoCompression:
322. 		bodyReader = ioutil.NopCloser(requestReader)
323. 	case otlp.GzipCompression:
324. 		preader, pwriter := io.Pipe()
325. 		go func() {
326. 			defer pwriter.Close()
327. 			gzipper := gzip.NewWriter(pwriter)
328. 			defer gzipper.Close()
329. 			_, err := io.Copy(gzipper, requestReader)
330. 			if err != nil {
331. 				otel.Handle(fmt.Errorf("otlphttp: failed to gzip request: %v", err))
332. 			}
333. 		}()
334. 		headers.Set("Content-Encoding", "gzip")
335. 		bodyReader = preader
336. 		contentLength = -1
337. 	}
338. 	return bodyReader, contentLength, headers
339. }
340.

