404. func exportKindToTemporality(ek export.ExportKind) metricpb.AggregationTemporality {
405. 	switch ek {
406. 	case export.DeltaExportKind:
407. 		return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_DELTA
408. 	case export.CumulativeExportKind:
409. 		return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_CUMULATIVE
410. 	}
411. 	return metricpb.AggregationTemporality_AGGREGATION_TEMPORALITY_UNSPECIFIED
412. }
